import{z as i,x as p,o as r,c as A,q as t,j as l,D as e,d as n,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"杠杆收购与私募股权","description":"","frontmatter":{"title":"杠杆收购与私募股权","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lbo-private-equity.md","filePath":"econ/lbo-private-equity.md","lastUpdated":1791063341000}'),d={name:"econ/lbo-private-equity.md"};function m(D,a,P,h,u,C){const B=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="杠杆收购与私募股权" tabindex="-1">杠杆收购与私募股权 <a class="header-anchor" href="#杠杆收购与私募股权" aria-label="Permalink to &quot;杠杆收购与私募股权&quot;">​</a></h1><div class="epigraph"><p>杠杆收购把自由现金流押成还本付息，把股权集中到发起人手中，使 Grossman–Hart 的免费搭车和 Jensen 的现金浪费同时被合同关掉。</p><footer>—— Jensen, Eclipse of the Public Corporation, Harvard Business Review 1989；Kaplan, Journal of Finance 1989；Kaplan and Strömberg, Journal of Economic Perspectives 2009</footer></div><p><a href="/econ/ma-synergy-payment">上一课</a>的战略并购常付股票、协同含糊。本课缺口是另一类控制权交易：LBO/PE 用高杠杆现金买下公众公司或分部，治理改善来自债务纪律与集中股权，而不是行业协同叙事。不重做 Travlos 的支付信号，不写 PE 基金的募资条款全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公众公司股权分散、董事会弱、FCF 高时，内部监督不足，全面要约又遇免费搭车。LBO：发起人与管理层持股大，\\(\\alpha\\) 内部化改善；银行与高收益债把未来现金锁死。Kaplan（1989）：经营变化与税、价值在样本中上升。Jensen（1989）预言公众公司在成熟行业被私募形式替代。缺口是把前几课装置装进一套合同：债务容量来自稳定 FCF，期限与契约来自银行，退出（IPO 或再出售）把择时再引进来。</p><p><span class="marginnote">PE 不限于敌意 LBO：也包括成长股权与困境债。本课主线是杠杆买下控制权。困境债接到第 11 章与 APR 偏离。</span></p><p><span class="marginnote">术语翻译（免费搭车）：收购里指小股东盘算「等别人先贱卖，我搭车分享改善后的增值」，于是没人肯先卖、要约失败。LBO 的解法是现金一次性买断加私下谈判，让这班车没得搭——Grossman–Hart 说谁来付监督的钱，LBO 答了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资本结构：初始杠杆极高，目标不是静态 \\(D^\\ast\\) 的舒适带，而是用债逼出效率，再随还本降杠杆（反向动态权衡）。失败态是积压与展期墙——高收益债与银行短债的组合正是期限课的压力测试。治理：董事会由 PE 控制，监督不再内生于 CEO 选独董。薪酬：管理层股权比例高，敏感度远高于 Jensen–Murphy 的公众 CEO。</p><p>退出：改善实现后，公开市场窗口决定是否 IPO——Baker–Wurgler 在 PE 退出上再现。资本预算：对 PE 而言 IRR 是基金报表语言；对企业仍应看 NPV 与债的风险转移。上一单元 IRR 陷阱：基金 IRR 依赖时间加权与再投资假设，不是项目接受规则。</p>',10)),(r(),l(o,null,{default:e(()=>[s(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FCF%5B%22%E7%A8%B3%E5%AE%9A%20FCF%22%5D%20--%3E%20DEBT%5B%22%E9%AB%98%E6%9D%A0%E6%9D%86%E8%BF%98%E6%9C%AC%22%5D%0A%20%20ALPHA%5B%22%E9%9B%86%E4%B8%AD%E8%82%A1%E6%9D%83%22%5D%20--%3E%20INT%5B%22%E6%94%B9%E5%96%84%E5%86%85%E9%83%A8%E5%8C%96%22%5D%0A%20%20DEBT%20--%3E%20DISC%5B%22%E7%BA%AA%E5%BE%8B%3A%20%E5%B0%91%E6%B5%AA%E8%B4%B9%22%5D%0A%20%20DEBT%20--%3E%20RISK%5B%22%E7%A7%AF%E5%8E%8B%E4%B8%8E%E5%B1%95%E6%9C%9F%22%5D%0A%20%20EXIT%5B%22IPO%20%2F%20%E5%87%BA%E5%94%AE%22%5D%20--%3E%20TIME%5B%22%E6%8B%A9%E6%97%B6%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与银行 vs 公募：LBO 融资是银行 + 高收益公募的混合，条款紧，再谈判靠主银行。证券化有时出现在资产侧。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是把代理成本转化成违约风险。纪律的收益与财务困境的成本是同一杠杆的两面。成功样本活过还本期；失败样本进第 11 章，APR 偏离与 DIP 决定 PE 股权是否归零。事前定价应含 Andrade–Kaplan 的财务困境成本。",-1)),(r(),l(o,null,{default:e(()=>[s(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEV%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E9%AB%98%E6%9D%A0%E6%9D%86%22%5D%20--%3E%20G%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E7%A8%B3%EF%BC%9A%E8%BF%98%E6%9C%AC%E9%80%BC%E5%87%BA%E6%95%88%E7%8E%87%22%5D%0A%20%20LEV%20--%3E%20B%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%96%AD%EF%BC%9A%E4%BB%98%E4%B8%8D%E5%87%BA%E6%9C%AC%E6%81%AF%22%5D%0A%20%20G%20--%3E%20WIN%5B%22%E4%BB%B7%E5%80%BC%E6%94%B9%E5%96%84%EF%BC%8CPE%20%E8%82%A1%E6%9D%83%E5%A2%9E%E5%80%BC%E9%80%80%E5%87%BA%22%5D%0A%20%20B%20--%3E%20BK%5B%22%E8%BF%9B%E7%AC%AC%2011%20%E7%AB%A0%E9%87%8D%E6%95%B4%22%5D%0A%20%20BK%20--%3E%20APR%5B%22APR%20%E5%81%8F%E7%A6%BB%E4%B8%8E%20DIP%20%E5%86%B3%E5%AE%9A%E6%B8%85%E5%81%BF%E9%A1%BA%E5%BA%8F%22%5D%0A%20%20APR%20--%3E%20ZERO%5B%22PE%20%E8%82%A1%E6%9D%83%E5%8F%AF%E8%83%BD%E5%BD%92%E9%9B%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>免费搭车：现金强制挤出公众股东，法律允许合并，Grossman–Hart 的补丁被用满。防御：毒丸可被董事会（若尚未被换）挡住敌意 LBO；友好 LBO 由现任参与，降落伞与管理层持股对齐。</p><h3 id="不是「杠杆创造价值」" tabindex="-1">不是「杠杆创造价值」 <a class="header-anchor" href="#不是「杠杆创造价值」" aria-label="Permalink to &quot;不是「杠杆创造价值」&quot;">​</a></h3><p>价值来自资产现金流改善与税盾，减去困境。杠杆是实施工具。把 LBO 溢价当成杠杆本身的魔力，违反 MM：无改善则只是切片加税再加破产概率。</p><p><span class="marginnote">直觉类比：不加改善、纯加杠杆，像把一块蛋糕切成更多块重新摆盘——蛋糕总量没变，只是风险与回报在不同块之间重新分配，还多付了「破产概率上升」这份切蛋糕的代价。</span></p><p><span class="marginnote">数字实例（债务纪律）：公司每年 FCF 1 亿，股权分散时这钱容易被花在低效扩张上；改成每年还本付息 0.9 亿后，管理层能自由支配的只剩 0.1 亿——「可乱花的钱」被合同砍掉九成，比任何董事会决议都硬。</span></p><p><span class="marginnote">Kaplan–Strömberg（2009）综述 PE 的经营与治理证据。机制课取合同结构，不把基金回报当成无风险 alpha。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成买卖价差与基金流水。下一课 VC：另一端——少债、多分阶段股权、高不确定性，实物期权与合同权利替代 LBO 的还本纪律。</p><p>后课默认：LBO 用集中股权解决免费搭车，用债解决 FCF；失败态是本单元写过的困境与展期。IRR 是基金语言，不是资本预算的接受规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LBO/PE：高 \\(\\alpha\\) 内部化改善，高杠杆锁 FCF，现金挤出公众股东。</li><li>纪律与困境是同一杠杆；退出再引入股权择时。</li><li>协同主要是治理，不是行业故事；MM 仍约束「纯切片」。</li><li>出处：Jensen, <em>HBR</em> 1989；Kaplan, <em>JF</em> 1989；Kaplan and Strömberg, <em>JEP</em> 2009。</li></ul>',11))])}const f=i(d,[["render",m]]);export{F as __pageData,f as default};
